using System.Text;
using UnityEngine;
using Framework.Grid;

namespace Game.Tests
{
    /// <summary>
    /// 汎用グリッド管理システムの動作確認用クラス。
    /// </summary>
    public class GridMapTest : MonoBehaviour
    {
        #region Fields

        [Header("マップ設定")]

        /// <summary>マップの横方向のマス数。</summary>
        [SerializeField]
        [Min(3)]
        [Tooltip("マップの横方向のマス数")]
        private int width = 15;

        /// <summary>マップの縦方向のマス数。</summary>
        [SerializeField]
        [Min(3)]
        [Tooltip("マップの縦方向のマス数")]
        private int height = 11;

        /// <summary>床を表すデータ値。</summary>
        private const int Floor = 0;

        /// <summary>壁を表すデータ値。</summary>
        private const int Wall = 1;

        /// <summary>動作確認用のマップデータ。</summary>
        private GridMap<int> map;

        #endregion

        #region Unity Methods

        private void Start()
        {
            CreateMap();
            PrintMap();
            TestGridMap();
        }

        private void OnDestroy()
        {
            // イベントの登録を解除する。
            if (map != null)
            {
                map.CellChanged -= OnCellChanged;
            }
        }

        #endregion

        #region Private Methods

        /// <summary>
        /// 外周が壁、内部が床となるマップを生成する。
        /// </summary>
        private void CreateMap()
        {
            map = new GridMap<int>(
                width,
                height,
                position =>
                {
                    // 外周に位置するマスか判定する。
                    bool isBorder =
                        position.x == 0 ||
                        position.y == 0 ||
                        position.x == width - 1 ||
                        position.y == height - 1;

                    return isBorder ? Wall : Floor;
                });

            // マス変更イベントを登録する。
            map.CellChanged += OnCellChanged;
        }

        /// <summary>
        /// マップの内容をUnity Consoleに出力する。
        /// </summary>
        private void PrintMap()
        {
            // 出力する文字列を構築するための変数。
            StringBuilder builder = new StringBuilder();

            builder.AppendLine(
                $"マップサイズ：{map.Width} × {map.Height}");

            // Y座標の大きい行から順に出力する。
            for (int y = map.Height - 1; y >= 0; y--)
            {
                for (int x = 0; x < map.Width; x++)
                {
                    builder.Append(
                        map[x, y] == Wall ? '#' : '.');
                }

                builder.AppendLine();
            }

            Debug.Log(builder.ToString());
        }

        /// <summary>
        /// グリッドの基本機能を検証する。
        /// </summary>
        private void TestGridMap()
        {
            // 床と壁のマス数を取得する。
            int floorCount =
                map.CountCells(value => value == Floor);

            int wallCount =
                map.CountCells(value => value == Wall);

            Debug.Log($"全マス数：{map.Count}");
            Debug.Log($"床の数：{floorCount}");
            Debug.Log($"壁の数：{wallCount}");

            // 範囲外判定を確認する。
            Debug.Assert(
                !map.IsInside(-1, 0),
                "範囲外判定に失敗しました。");

            // 座標(1, 1)を床から壁に変更する。
            map.SetCell(1, 1, Wall);

            Debug.Assert(
                map.GetCell(1, 1) == Wall,
                "マスの変更に失敗しました。");

            // 範囲外の安全な取得を確認する。
            bool result = map.TryGetCell(
                new Vector2Int(-1, 0),
                out int value);

            Debug.Assert(
                !result,
                "範囲外の取得判定に失敗しました。");

            // 変更後のマップを出力する。
            PrintMap();
        }

        /// <summary>
        /// マスの変更内容をConsoleに出力する。
        /// </summary>
        /// <param name="position">変更された座標</param>
        /// <param name="oldValue">変更前のデータ</param>
        /// <param name="newValue">変更後のデータ</param>
        private void OnCellChanged(
            Vector2Int position,
            int oldValue,
            int newValue)
        {
            Debug.Log(
                $"マス変更：{position} " +
                $"{oldValue} → {newValue}");
        }

        #endregion
    }
}
